@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @Mock
    private EmailService emailService;

    @InjectMocks  // injects the two mocks above
    private OrderService orderService;

    @Test
    void shouldSendEmailWhenOrderIsPlaced() {
        var order = new Order(1L, "Laptop");
        when(orderRepository.save(any(Order.class)))
            .thenReturn(order);

        orderService.placeOrder(order);

        verify(emailService).sendConfirmation(order);  // assert interaction
    }
}

@ExtendWith(MockitoExtension.class)
class UserServiceTest {

    @Mock
    private UserRepository userRepository;

    @InjectMocks
    private UserService userService;

    @Test
    void shouldReturnUserWhenFound() {
        var user = new User(1L, "Alice");
        when(userRepository.findById(1L))  // stub for ID 1
            .thenReturn(Optional.of(user));

        // BUG: code calls findById(2L) instead of 1L
        var result = userService.getUserById(2L);

        // Strict stubbing FAILS here: stub for 1L was never used
        // and findById(2L) was called without a stub
    }
}

class PaymentServiceTest {

    @Test
    void shouldProcessPaymentWithDynamicGateway() {
        // Create mocks programmatically
        var paymentGateway = Mockito.mock(PaymentGateway.class);
        var auditLogger = Mockito.mock(AuditLogger.class);

        var service = new PaymentService(paymentGateway, auditLogger);

        when(paymentGateway.charge(any()))
            .thenReturn(true);

        var result = service.processPayment(new Payment(100.0));

        assertThat(result).isTrue();
        verify(auditLogger).log("Payment processed");
    }

    // Helper method creating mock dynamically
    private <T> List<T> mockListOf(Class<T> type) {
        return Mockito.mock(List.class);  // useful for generic types
    }
}

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @Mock
    private EmailService emailService;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldNotSaveOrEmailWhenValidationFails() {
        var invalidOrder = new Order(null, "");  // missing required fields

        assertThrows(ValidationException.class, () -> {
            orderService.placeOrder(invalidOrder);
        });

        verify(orderRepository, never()).save(any());  // database not touched
        verify(emailService, never()).sendConfirmation(any());  // no email sent
    }
}

// Pure unit test - no Spring context
@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldCalculateTotal() {
        when(orderRepository.findById(1L))
            .thenReturn(Optional.of(new Order(1L, "Laptop", 1000.0)));

        var total = orderService.calculateTotal(1L);

        assertThat(total).isEqualTo(1000.0);
    }
}

